-- Cloud copy of each synced app table, same columns as the phone's SQLite
-- (lib/core/db/tables.dart) plus account_id, so the data can be read table
-- by table in D1. Generated by scripts/mirror-tables.mjs --sql. sync_rows
-- stays the sync log; the worker keeps these tables equal to it on every
-- push. Existing rows are copied over below.

CREATE TABLE IF NOT EXISTS business_profiles (
  account_id TEXT NOT NULL,
  id TEXT NOT NULL,
  name TEXT,
  phone TEXT,
  address TEXT,
  logo_path TEXT,
  upi_id TEXT,
  signature_path TEXT,
  invoice_prefix TEXT,
  quotation_prefix TEXT,
  trades TEXT,
  user_type TEXT,
  settings_json TEXT,
  created_at INTEGER,
  updated_at INTEGER,
  PRIMARY KEY (account_id, id)
);

INSERT OR REPLACE INTO business_profiles (account_id, id, name, phone, address, logo_path, upi_id, signature_path, invoice_prefix, quotation_prefix, trades, user_type, settings_json, created_at, updated_at)
SELECT account_id, row_id, json_extract(data, '$.name'), json_extract(data, '$.phone'), json_extract(data, '$.address'), json_extract(data, '$.logo_path'), json_extract(data, '$.upi_id'), json_extract(data, '$.signature_path'), json_extract(data, '$.invoice_prefix'), json_extract(data, '$.quotation_prefix'), json_extract(data, '$.trades'), json_extract(data, '$.user_type'), json_extract(data, '$.settings_json'), json_extract(data, '$.created_at'), json_extract(data, '$.updated_at')
FROM sync_rows WHERE tbl = 'business_profiles' AND deleted = 0;

